<?php defined('ABSPATH')||exit; $theme=get_option('eaiw_theme','dark'); $jobs=EAIW_Job_Queue::recent(100); $labels=['pending'=>'در انتظار','processing'=>'در حال پردازش','completed'=>'تکمیل‌شده','failed'=>'ناموفق']; ?>
<div class="wrap eaiw-nebula-wrap <?php echo $theme==='light'?'eaiw-light':'';?>"><div class="eaiw-nebula-bg"></div><div class="eaiw-topbar"><div class="eaiw-brand"><div class="eaiw-logo">⏳</div><div><h1>صف کارها</h1><p>کارهای پس‌زمینه و وضعیت اجرای آن‌ها را مدیریت کنید.</p></div></div><a href="<?php echo esc_url(admin_url('admin.php?page=eaiw-nebula'));?>" class="eaiw-btn eaiw-btn-ghost">بازگشت به پیشخوان</a></div><div class="eaiw-card"><h3>آخرین کارها</h3><?php if(!$jobs):?><div class="eaiw-empty">هنوز کاری در صف ثبت نشده است.</div><?php else:?><div class="eaiw-jobs-table"><table class="eaiw-table"><thead><tr><th>شناسه</th><th>نوع کار</th><th>وضعیت</th><th>تلاش</th><th>زمان ایجاد</th><th>خطا</th><th>عملیات</th></tr></thead><tbody><?php foreach($jobs as $job):?><tr><td>#<?php echo (int)$job['id'];?></td><td><?php echo esc_html($job['job_type']);?></td><td><span class="eaiw-badge <?php echo $job['status']==='completed'?'green':($job['status']==='failed'?'red':'purple');?>"><?php echo esc_html($labels[$job['status']]??$job['status']);?></span></td><td><?php echo (int)$job['attempts'];?></td><td><?php echo esc_html($job['created_at']);?></td><td><?php echo esc_html($job['error_text']?:'—');?></td><td><?php if($job['status']==='failed'):?><button class="eaiw-btn eaiw-btn-ghost eaiw-job-retry" data-id="<?php echo (int)$job['id'];?>">اجرای دوباره</button><?php elseif(in_array($job['status'],['pending','processing'],true)):?><button class="eaiw-btn eaiw-btn-ghost eaiw-job-cancel" data-id="<?php echo (int)$job['id'];?>">لغو</button><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><script>jQuery(function($){$('.eaiw-job-retry,.eaiw-job-cancel').on('click',function(){const b=$(this),retry=b.hasClass('eaiw-job-retry'),action=retry?'eaiw_job_retry':'eaiw_job_cancel';if(!retry&&!window.confirm('این کار لغو شود؟'))return;b.prop('disabled',true).text('در حال انجام...');$.post(EAIW.ajax,{action:action,id:b.data('id'),_ajax_nonce:EAIW.nonce},function(r){if(r.success)location.reload();else{b.prop('disabled',false).text(retry?'اجرای دوباره':'لغو');window.alert(r.data||'عملیات انجام نشد.');}});});});</script></div>
